<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { ElMessage } from 'element-plus';

import { api } from '../api';
import { dateText, errorText, moduleNames, post, statusText } from '../saas';
import '../saas.css';
const current=ref<any>(null);const loading=ref(false);const confirming=ref(false);const error=ref('');
const metrics=computed(()=>{const u=current.value?.usage??{};return [{name:'平台成员',value:u.users??u.members??0},{name:'运营企业',value:u.enterprises??0},{name:'接入车辆',value:u.vehicles??0},{name:'已开通模块',value:(current.value?.workspace?.modules??current.value?.modules??[]).length}]});
const checklist=computed(()=>{const value=current.value?.checklist;if(Array.isArray(value))return value.map(item=>({...item,path:({members:'/city/members',rules:'/system/business-rules',enterprises:'/archives/enterprises',telemetry:'/operations/realtime'} as Record<string,string>)[item.key]}));if(value&&typeof value==='object')return Object.entries(value).map(([name,done])=>({name,done}));return []});
async function load(){loading.value=true;error.value='';try{current.value=await api('/saas/current')}catch(e){error.value=errorText(e)}finally{loading.value=false}}
async function confirmRules(){confirming.value=true;try{await post('/saas/current/confirm-rules');ElMessage.success('本市业务规则已确认');await load()}catch(e){ElMessage.error(errorText(e))}finally{confirming.value=false}}
async function read(id:string){try{await post(`/saas/notices/${id}/read`);await load()}catch(e){ElMessage.error(errorText(e))}}
onMounted(load);
</script>
<template><div class="saas-page" v-loading="loading"><h1 class="sr-only">平台授权</h1><div v-if="error" class="saas-error" role="alert"><span>{{error}}</span><el-button @click="load">重试</el-button></div><template v-else-if="current"><el-alert v-if="!current.workspace" title="当前账号未关联城市工作空间" type="info" :closable="false"/><template v-else><el-alert v-if="current.workspace.status!=='ACTIVE'||(current.workspace.validUntil&&new Date(current.workspace.validUntil).getTime()<Date.now())" :title="`${statusText(current.workspace.status)} · 请查看授权期限或提交变更申请`" type="warning" :closable="false"/><div class="saas-summary"><div v-for="metric in metrics" :key="metric.name" class="saas-metric"><span>{{metric.name}}</span><strong>{{metric.value}}</strong></div></div><section class="saas-panel"><div class="saas-heading"><h2>{{current.workspace.cityName}}工作空间</h2><el-tag :type="current.workspace.status==='ACTIVE'?'success':'warning'">{{statusText(current.workspace.status)}}</el-tag></div><el-descriptions :column="2" border><el-descriptions-item label="城市编码">{{current.workspace.cityCode}}</el-descriptions-item><el-descriptions-item label="授权有效期">{{current.workspace.validUntil?dateText(current.workspace.validUntil):'长期有效'}}</el-descriptions-item><el-descriptions-item label="业务模块" :span="2"><div class="saas-module-tags"><el-tag v-for="code in (current.workspace.modules??current.modules??[])" :key="code" type="info">{{moduleNames[code]??code}}</el-tag></div></el-descriptions-item><el-descriptions-item label="车辆配额">{{current.workspace.quotas?.vehicles??'未设置'}}</el-descriptions-item><el-descriptions-item label="开通时间">{{dateText(current.workspace.createdAt)}}</el-descriptions-item></el-descriptions><div class="saas-actions" style="margin-top:16px"><router-link to="/city/members"><el-button>管理本市成员</el-button></router-link><span class="saas-subtle">功能调整、续期和管理员变更请线下联系省级管理员。</span></div></section><section class="saas-panel"><h2>初始化进度</h2><el-table :data="checklist" empty-text="暂无初始化待办"><el-table-column label="事项" min-width="220"><template #default="{row}">{{row.name??row.label??row.title??row.key}}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><el-tag :type="row.done||row.completed||row.complete?'success':'info'">{{row.done||row.completed||row.complete?'已完成':'待完成'}}</el-tag></template></el-table-column><el-table-column label="下一步" width="230"><template #default="{row}"><div v-if="row.key==='rules'" class="saas-actions"><router-link :to="row.path"><el-button text type="primary">查看规则</el-button></router-link><el-button v-if="!row.complete" text type="primary" :loading="confirming" @click="confirmRules">确认已核验</el-button></div><router-link v-else-if="row.path" :to="row.path"><el-button text type="primary">前往处理</el-button></router-link><span v-else>—</span></template></el-table-column></el-table></section><section class="saas-panel"><h2>平台通知</h2><el-empty v-if="!current.notices?.length" description="暂无平台通知" :image-size="60"/><article v-for="notice in current.notices" :key="notice.id" class="saas-notice"><div class="saas-heading"><strong>{{notice.title}}</strong><el-button v-if="!notice.readAt" text type="primary" @click="read(notice.id)">标为已读</el-button><el-tag v-else type="info" size="small">已读</el-tag></div><p>{{notice.content}}</p><span class="saas-subtle">{{dateText(notice.createdAt)}}</span></article></section></template></template></div></template>
